    if (M <= 1) return 0; // If there's only one or no island to visit, the tour length is zero.

    // Calculate the initial total tour length
    int totalTourLength = 0;
    for (int i = 1; i < M; i++) {
        totalTourLength += Math.abs(X[i] - X[i - 1]);
    }

    // Find the minimum tour length by closing one bridge
    int minTourLength = totalTourLength;
    for (int i = 1; i < M - 1; i++) {
        // Calculate the tour length if the bridge between X[i-1] and X[i] is closed
        int tourLengthWithBridgeClosed = totalTourLength
                - Math.abs(X[i] - X[i - 1])
                - Math.abs(X[i + 1] - X[i])
                + Math.abs(X[i + 1] - X[i - 1]);

        minTourLength = Math.min(minTourLength, tourLengthWithBridgeClosed);
    }

    return minTourLength;
}

